"""Writes hosting/public/config.js from lib/config/supabase_config.dart.

The recipient's page (hosting/public/r) calls the database with the same
publishable key as the app. Run after the key changes:
    python3 scripts/hosting_config.py
"""
import pathlib
import re

root = pathlib.Path(__file__).resolve().parent.parent
dart = (root / "lib/config/supabase_config.dart").read_text()
url = re.search(r"url = '([^']+)'", dart).group(1)
key = re.search(r"anonKey =\s*'([^']+)'", dart).group(1)
(root / "hosting/public/config.js").write_text(
    "// Generated by scripts/hosting_config.py from supabase_config.dart.\n"
    f"window.NATA = {{ url: '{url}', key: '{key}' }};\n"
)
print("hosting/public/config.js written")
